package com.knowflow.controller;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"knowflow.product.adaptive-learning.enabled=true","knowflow.product.interview-learning.enabled=true","knowflow.product.private-quiz.enabled=true","knowflow.product.tutor.enabled=true","knowflow.product.tutor-coaching.enabled=true","server.address=127.0.0.1"})
class ProductInterleavedHttpTest extends ProductFeedbackHttpTest {
 @Autowired com.knowflow.mapper.DocDocumentMapper docs;@Autowired com.knowflow.mapper.DocCategoryMapper cats;@Autowired com.knowflow.mapper.KgEntityMapper kg;
 @Test void alternationFrozenVersionsOriginalGradingImmutableHistoryAndScope()throws Exception{
  var a=wrong();var b=wrong();var cat=new com.knowflow.entity.DocCategory();cat.setOwnerId(owner);cat.setName("交错合成知识点");cat.setCode(UUID.randomUUID().toString());cat.setStatus(1);cats.insert(cat);var doc=new com.knowflow.entity.DocDocument();doc.setCategoryId(cat.getId());doc.setTitle("合成原资料");doc.setContent("MVCC 与 Java 并发合成资料");doc.setStatus(1);docs.insert(doc);var kids=new ArrayList<Long>();for(String name:List.of("MVCC","Java并发")){var k=new com.knowflow.entity.KgEntity();k.setCategoryId(cat.getId());k.setDocId(doc.getId());k.setName(name);k.setType("CONCEPT");kg.insert(k);kids.add(k.getId());}
  var r=Map.of("requestId",UUID.randomUUID().toString(),"count",4,"topics",List.of(Map.of("knowledgeId",kids.get(0),"quizId",a.quiz()),Map.of("knowledgeId",kids.get(1),"quizId",b.quiz())));String root="/api/learning/interleaved-practice";var draft=call("POST",root,r,owner,200);long id=draft.path("id").asLong();assertEquals(4,draft.path("items").size());for(int i=0;i<4;i++){var item=draft.path("items").get(i);assertEquals(kids.get(i%2).longValue(),item.path("knowledgeId").asLong());assertEquals(1,item.path("quizVersion").asInt());assertFalse(item.path("attempt").path("questions").get(0).has("answer"));}assertEquals(id,call("POST",root,r,owner,200).path("id").asLong());
  var result=call("POST",root+"/"+id+"/submit",Map.of("answers",List.of("true","true","false","false")),owner,200);assertEquals("COMPLETED",result.path("state").asText());for(var item:result.path("items"))assertEquals(100,item.path("attempt").path("score").asInt());call("POST",root+"/"+id+"/submit",Map.of("answers",List.of("true","true","false","false")),owner,200);call("POST",root+"/"+id+"/submit",Map.of("answers",List.of("false","true","false","false")),owner,409);for(long u:new long[]{owner+1,owner+2})call("GET",root+"/"+id,null,u,404);call("GET",root+"/"+id,null,0,401);sql.update("UPDATE learning_note SET deleted=1 WHERE id=?",a.note());call("GET",root+"/"+id,null,owner,404);assertEquals("SOURCE_UNAVAILABLE",call("GET",root,null,owner,200).get(0).path("state").asText());
 }
}
